// Sign the bodiless GET the same way Convex expects:
//   HMAC-SHA256(secret, "<timestamp>.GET /overdue-loans")
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!secret || !base) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET and CONVEX_SITE_URL must be set in the n8n environment');
}
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.GET /overdue-loans`).digest('hex');
return [{ json: { url: `${base}/overdue-loans`, timestamp, signature } }];

// One item per overdue loan. dayKey is the idempotency scope: Convex stores at
// most one reminder per (loanId, dayKey), so re-running today is harmless.
const loans = $input.first().json.loans || [];
const dayKey = new Date().toISOString().slice(0, 10);
return loans.map((loan) => ({
  json: {
    loanId: loan.loanId,
    toolName: loan.toolName,
    dueDate: loan.dueDate,
    daysOverdue: loan.daysOverdue,
    borrowerName: loan.borrowerName,
    borrowerEmail: loan.borrowerEmail,
    dayKey,
    channel: $env.LENDLOOP_NOTIFY_VIA === 'email' ? 'email' : 'mock',
    subject: `Reminder: ${loan.toolName} was due ${loan.dueDate}`,
    text: `Hi ${loan.borrowerName},\n\nA quick reminder that ${loan.toolName} was due back on ${loan.dueDate} (${loan.daysOverdue} day(s) ago). Please arrange the return with the owner through LendLoop.\n\nThanks,\nLendLoop`,
  },
}));

// Mock channel: log instead of sending, then treat as sent.
const m = $input.item.json;
console.log(`[LendLoop mock reminder] to=${m.borrowerEmail} loan=${m.loanId} day=${m.dayKey}`);
return { json: { ...m, status: 'sent' } };

// Email node output does not carry our fields; read them from the Split node
// for the same item index.
const src = $('Split into loans').item.json;
return { json: { loanId: src.loanId, dayKey: src.dayKey, status: 'sent' } };

// Error output of the email node: record the failure so it is visible on the
// loan in the app instead of disappearing into a log.
const src = $('Split into loans').item.json;
const err = $input.item.json.error;
const message = typeof err === 'string' ? err : (err && err.message) || 'email send failed';
return { json: { loanId: src.loanId, dayKey: src.dayKey, status: 'failed', error: String(message).slice(0, 300) } };

// Build the raw JSON body and sign it: HMAC-SHA256(secret, "<timestamp>.<body>").
// The body string is sent verbatim so the receiver hashes exactly these bytes.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
const j = $input.item.json;
const body = JSON.stringify({
  loanId: j.loanId,
  dayKey: j.dayKey,
  status: j.status,
  error: j.error,
  idempotencyKey: `reminder:${j.loanId}:${j.dayKey}`,
});
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { url: `${base}/reminder-status`, body, timestamp, signature } };
